import{z as s,x as n,o as t,c as h,q as r,j as i,D as e,d as m,s as E,S as R}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"概率夏普 PSR","description":"","frontmatter":{"title":"概率夏普 PSR","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/probabilistic-sharpe.md","filePath":"quant/probabilistic-sharpe.md","lastUpdated":1791063341000}'),o={name:"quant/probabilistic-sharpe.md"};function p(l,a,A,d,B,P){const S=n("Mermaid");return t(),h("div",null,[a[2]||(a[2]=r('<h1 id="概率夏普-psr" tabindex="-1">概率夏普 PSR <a class="header-anchor" href="#概率夏普-psr" aria-label="Permalink to &quot;概率夏普 PSR&quot;">​</a></h1><div class="epigraph"><p>夏普是估计量。我们要的是：在估计了偏度、峰度与样本量之后，真实夏普超过某条预先声明阈值的概率。</p><footer>—— Bailey and López de Prado, The Sharpe Ratio Efficient Frontier, Journal of Risk, 2012</footer></div><p><a href="/quant/bailey-dsr">上一课</a>读毕 Deflated Sharpe 原文的两层修正。 <a href="/quant/deflated-sharpe">Deflated Sharpe</a> 把 PSR 当成 DSR 的构件一笔带过：先有「超过阈值的概率」，再把阈值换成多次试验的极值。Bailey 与 López de Prado 2012 年在 <em>Journal of Risk</em> 的 <em>The Sharpe Ratio Efficient Frontier</em> 里，PSR 是<strong>主对象</strong>。它回答单次（或预先指定的）策略：给定观测夏普、样本长度、偏度与峰度，\\(\\mathbb{P}(\\mathrm{SR}\\gt \\mathrm{SR}^*)\\) 的渐近估计是多少。\\(\\mathrm{SR}^*\\) 可以是 0，可以是融资与风险厌恶要求的最低夏普，也可以是另一个基准策略的夏普。DSR 是两年后才加上「被选过的最大值」这一层。本篇写 PSR 本身、非正态修正、两条策略的比较，以及原文的夏普有效前沿——在给定高阶矩下，夏普不能任意高。不把 PSR 再讲成 DSR。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>样本夏普 \\(\\widehat{\\mathrm{SR}}=\\bar x/s_x\\) 即使在 IID 正态下也有误差；非正态时误差更大。从业者却常用「夏普大于 1」或「大于 2」当确定性标签。Opdyke（2007）给出夏普的渐近分布；Mertens 把偏度与峰度写进方差。Bailey–López de Prado 把这些收成一个单边概率：</p> \\[\\widehat{\\mathrm{PSR}}(\\mathrm{SR}^*)=Z\\left[\\frac{(\\widehat{\\mathrm{SR}}-\\mathrm{SR}^*)\\sqrt{T-1}}{\\sqrt{1-\\hat\\gamma_3\\widehat{\\mathrm{SR}}+\\frac{\\hat\\gamma_4-1}{4}\\widehat{\\mathrm{SR}}^2}}\\right], \\]<p>\\(Z\\) 为标准正态 CDF。直观：\\(\\widehat{\\mathrm{SR}}\\) 越高于阈值、\\(\\sqrt{T}\\) 越大、高阶矩越接近正态，PSR 越高。左偏或肥尾抬高分母，同样的点估计对应更低的 PSR。问题是把夏普从「表上的一个数」还原成「对 \\(\\mathrm{SR}\\gt \\mathrm{SR}^*\\) 的检验」。</p><p><span class="marginnote">直觉类比：PSR 像选举后的「胜选概率」——不问「谁领先」（点估计），而问「领先幅度扣除统计误差后赢面多大」。同样的 1.0 夏普，两年样本和二十五年样本的赢面完全不同，左偏肥尾还要再打折扣。</span></p><p>阈值必须预先声明。看完 \\(\\widehat{\\mathrm{SR}}=1.4\\) 再把 \\(\\mathrm{SR}^*\\) 设为 1.3，PSR 接近 1 没有信息。合法的 \\(\\mathrm{SR}^*\\)：0；资金成本折明年化后的最低可接受；或对照组的样本夏普（比较用）。</p><h3 id="两条策略的-psr-不是两个-psr-相减" tabindex="-1">两条策略的 PSR 不是两个 PSR 相减 <a class="header-anchor" href="#两条策略的-psr-不是两个-psr-相减" aria-label="Permalink to &quot;两条策略的 PSR 不是两个 PSR 相减&quot;">​</a></h3><p>比较 A 与 B，应对超额差 \\(x_t^A-x_t^B\\) 直接算夏普，再对这个差的夏普做 PSR，阈值通常为 0。分别报告 PSR(A)、PSR(B) 再看谁大，会忽略相关：高度相关的两个策略，差的夏普标准误远小于「两个独立夏普之差」。原文的比较框架针对的是差，不是两个概率的排序。基准必须可投资且与 A 同期，否则差的夏普没有实施意义。</p><p><span class="marginnote">年化约定要与 \\(T\\) 一致。用年化夏普、却把 \\(T\\) 当交易日数而不把阈值与方差同步年化，会把 PSR 算爆。应在同一频率上算 \\(\\widehat{\\mathrm{SR}}\\) 与 \\(\\mathrm{SR}^*\\)，再年化只用于展示。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>输入：同一频率的超额收益序列（已扣费、已含融资），\\(T\\)、\\(\\widehat{\\mathrm{SR}}\\)、\\(\\hat\\gamma_3\\)、\\(\\hat\\gamma_4\\)，以及预先写死的 \\(\\mathrm{SR}^*\\)。短样本的峰度极噪，应报告 PSR 对 \\(\\gamma_4\\) 截尾或 Winsorize 的敏感性，而不是只报一个点。序列相关时，先把有效样本量换成长期方差意义下的 \\(T_{\\mathrm{eff}}\\)（Newey–West 或 Lo 的调整），再进入公式；假装日度点独立，PSR 会虚高，见 <a href="/quant/ir-sharpe">IR / Sharpe</a>。</p><p>最小轨迹长度（MinTRL）：原文问，要把 PSR 推到某置信度，区分 \\(\\mathrm{SR}^*\\) 与真夏普，需要多少年。所需长度大致随 \\((\\mathrm{SR}-\\mathrm{SR}^*)^{-2}\\) 增长。高换手策略看起来 \\(T\\) 很大，有效独立信息可能很少；用日历天数去套 MinTRL 会低估需要的样本。这与 DSR 的 \\(\\mathrm{SR}_0\\) 是不同计算：MinTRL 假定你已经指定了一个策略和一个阈值，没有「选了 \\(N\\) 次」这一层。</p><p><span class="marginnote">数字实例：MinTRL 大致按「夏普差平方的倒数」增长——真夏普比阈值高 1.0 时，两年样本也许够用；只高 0.25 时，需要的样本约是前者的 16 倍（\\(1/0.25^2\\)）。「只差一点点」的策略最烧数据。</span></p><h3 id="夏普有效前沿-高阶矩限制-sr" tabindex="-1">夏普有效前沿：高阶矩限制 SR <a class="header-anchor" href="#夏普有效前沿-高阶矩限制-sr" aria-label="Permalink to &quot;夏普有效前沿：高阶矩限制 SR&quot;">​</a></h3><p>原文的「efficient frontier」不是 Markowitz 的 \\(\\mu\\)–\\(\\sigma\\) 前沿。它说：给定偏度与峰度（以及矩存在），样本夏普不能任意大——极端夏普与极端高阶矩互相约束。观测到又高又稳的夏普、同时声称收益接近正态，往往自相矛盾：要么矩没估计对，要么样本不够展示左尾。前沿给出一个诊断：把 \\((\\widehat{\\mathrm{SR}},\\hat\\gamma_3,\\hat\\gamma_4)\\) 标在图上，若落在不可能区域附近，应怀疑数据清洗、截断损失或卖出期权式的未实现左尾。短波动策略的样本 PSR 可以很高，直到左尾到来；前沿提醒 PSR 仍是渐近陈述，不是对跳跃风险的保险。</p><p><span class="marginnote">对收益做去极值、截断回撤年、换波动估计，都会改变 \\(\\widehat{\\mathrm{SR}}\\) 与高阶矩，从而改变 PSR。这些属于额外试验，晋级到 DSR 时 \\(N\\) 应增加，而不是继续声称「只算了一次 PSR」。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>PSR 的机制是 Wald 型单侧检验：分子是点估计相对阈值的距离，分母是考虑了高阶矩的标准误，再映射到正态概率。它比「夏普是否大于 1」多了样本量与形状，比自举便宜。正态 CDF 的代价是：真实抽样分布在小 \\(T\\)、大峰度下并不正态，PSR 的 0.95 不是精确的 95% 置信。大样本、近对称时近似可用；日内肥尾、两年样本时，应把 PSR 当排序工具，并用自举核对。</p>',21)),(t(),i(R,null,{default:e(()=>[E(S,{id:"mermaid-59",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E8%A7%82%E6%B5%8B%20SR_hat%20%E5%AF%B9%E7%85%A7%E9%98%88%E5%80%BC%20SR*%22%5D%20--%3E%20GAP%5B%22%E8%B7%9D%E7%A6%BB%E8%B6%8A%E5%A4%A7%EF%BC%8CPSR%20%E8%B6%8A%E9%AB%98%22%5D%0A%20%20SK%5B%22%E5%B7%A6%E5%81%8F%EF%BC%88%CE%B33%20%E4%B8%BA%E8%B4%9F%EF%BC%89%22%5D%20--%3E%20SE%5B%22%E5%88%86%E6%AF%8D%EF%BC%9A%E9%AB%98%E9%98%B6%E7%9F%A9%E6%A0%87%E5%87%86%E8%AF%AF%22%5D%0A%20%20KU%5B%22%E8%82%A5%E5%B0%BE%EF%BC%88%CE%B34%20%E5%A4%A7%EF%BC%89%22%5D%20--%3E%20SE%0A%20%20SE%20--%3E%20BIG%5B%22%E6%A0%87%E5%87%86%E8%AF%AF%E8%B6%8A%E5%A4%A7%EF%BC%8CPSR%20%E8%B6%8A%E4%BD%8E%22%5D%0A%20%20NN%5B%22%E6%A0%B7%E6%9C%AC%E6%9B%B4%E9%95%BF%EF%BC%88sqrt%20T-1%EF%BC%89%22%5D%20--%3E%20SHR%5B%22%E8%AF%AF%E5%B7%AE%E7%BC%A9%E5%B0%8F%EF%BC%8CPSR%20%E4%B8%8A%E5%8D%87%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[m(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r('<p><span class="marginnote">为什么重要：分母里的高阶矩是 PSR 与「拍脑袋比夏普」的分水岭。同一份 1.4 的夏普，在近正态的套利收益里可能是真技能，在卖出期权的负偏肥尾收益里可能只是左尾还没到——公式里那两个 \\(\\gamma\\) 就是用来把这两种情况分开的。</span></p><p>与 Sortino、Calmar 的差别：那些换分母或换路径泛函，仍是点估计。PSR 不改变绩效定义，只给<strong>同一个夏普</strong>配上推断。产品契约若承诺的是下行偏差，应另做下行比的推断，而不是用 PSR 假装已经管了左尾——PSR 只通过 \\(\\gamma_3,\\gamma_4\\) 部分进入左尾，不读取最大回撤。</p><h3 id="从-psr-到-dsr-只改阈值" tabindex="-1">从 PSR 到 DSR 只改阈值 <a class="header-anchor" href="#从-psr-到-dsr-只改阈值" aria-label="Permalink to &quot;从 PSR 到 DSR 只改阈值&quot;">​</a></h3><p>\\(N=1\\) 且 \\(\\mathrm{SR}^*\\) 取你的最低可接受夏普时，DSR 与 PSR 重合。一旦存在未申报的搜索，继续报 PSR\\((0)\\) 是在用错误的原假设。正确升级是把 \\(\\mathrm{SR}^*\\) 换成 \\(\\mathrm{SR}_0(N,V)\\)，即 <a href="/quant/bailey-dsr">原文 DSR</a>。两者在代码里应是同一函数、不同阈值，而不是两套互相竞争的「更好的夏普」。研报应同时给：预先指定阈值的 PSR（技能相对产品契约），以及计入 \\(N\\) 的 DSR（技能相对搜索过程）。缺一个，叙事就不完整。</p><p><span class="marginnote">常见误区：把 PSR(0) 报得很高就当策略过关。若你其实试过 50 组参数才得到这个夏普，原假设早已不是「夏普为 0」，而是「50 次尝试里最好的那个是否超过运气」——后者才是 DSR 回答的问题。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>PSR 高不等于可交易：成本应先进入 \\(x_t\\)。PSR 也不处理标签泄漏与切分选择；那是 purge 与 CPCV 的事。不要对滚动窗口的每一段都算 PSR 再挑选最高的那段展示——那是把 PSR 当成新的选择对象。截面因子的 \\(t\\) 统计量有自己的多重检验文献，不要用 PSR 去替代 Harvey–Liu–Zhu。</p><p>估计 \\(\\gamma_3,\\gamma_4\\) 需要比估计均值更多的样本。极端值对峰度的影响可以单独翻转 PSR 的结论，应报告剔除最大亏损日之后的 PSR 作为压力，而不是把剔除当作正式收益定义——除非产品规则本来就会截断。</p><p><span class="marginnote">PSR 的 \\(Z[\\cdot]\\) 在自变量很大时饱和在 1 附近，失去分辨率。比较两个都「PSR=1.000」的策略，应回到差的夏普、路径分布与经济约束，而不是比更多小数位。</span></p>',9)),(t(),i(R,null,{default:e(()=>[E(S,{id:"mermaid-87",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E8%B6%85%E9%A2%9D%E6%94%B6%E7%9B%8A%20x_t%20%E5%B7%B2%E6%89%A3%E8%B4%B9%22%5D%20--%3E%20MOM%5B%22SR_hat%2C%20T%2C%20%E5%81%8F%E5%BA%A6%2C%20%E5%B3%B0%E5%BA%A6%22%5D%0A%20%20TH%5B%22%E9%A2%84%E5%85%88%E5%A3%B0%E6%98%8E%E7%9A%84%20SR*%22%5D%20--%3E%20PSR%5B%22PSR%20%3D%20Z(%E6%A0%87%E5%87%86%E5%8C%96%E8%B7%9D%E7%A6%BB)%22%5D%0A%20%20MOM%20--%3E%20PSR%0A%20%20PSR%20--%3E%20USE%7B%22%E7%94%A8%E9%80%94%22%7D%0A%20%20USE%20--%3E%7C%22%E5%8D%95%E7%AD%96%E7%95%A5%20vs%20%E5%A5%91%E7%BA%A6%E9%98%88%E5%80%BC%22%7C%20REP%5B%22%E6%8A%A5%E5%91%8A%20PSR(SR*)%22%5D%0A%20%20USE%20--%3E%7C%22A%20%E5%AF%B9%20B%22%7C%20DIFF%5B%22%E5%AF%B9%20xA-xB%20%E5%81%9A%20PSR(0)%22%5D%0A%20%20USE%20--%3E%7C%22%E5%AD%98%E5%9C%A8%20N%20%E6%AC%A1%E6%90%9C%E7%B4%A2%22%7C%20DSR%5B%22%E6%8A%8A%20SR*%20%E6%8D%A2%E6%88%90%20SR_0%3A%20DSR%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[m(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=r('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>PSR 是 2012 年原文的主统计量：在非正态下，观测夏普超过预先声明阈值的渐近概率。</li><li>比较两个策略应对收益差做 PSR，而不是比较两个概率；频率、\\(T\\) 与阈值必须一致。</li><li>夏普有效前沿用高阶矩限制「可能的」夏普，用于诊断截断左尾与自相矛盾的矩。</li><li>\\(N=1\\) 时 DSR 退化为 PSR；有搜索时必须升级阈值，两者是同一函数的两种用法。</li><li>出处：Bailey and López de Prado, <em>The Sharpe Ratio Efficient Frontier</em>, Journal of Risk, 2012；Opdyke, <em>Journal of Asset Management</em>, 2007；Lo, <em>FAJ</em>, 2002；DSR 见 Bailey and López de Prado, <em>JPM</em>, 2014。</li></ul>',2))])}const f=s(o,[["render",p]]);export{D as __pageData,f as default};
